// Este nodo crea las tareas del Estudio Rivas para probar el workflow.
// En la Etapa 4 estos datos de ejemplo se reemplazan por los emails reales de Gmail.
//
// return entrega el resultado del nodo al nodo siguiente.
// Los corchetes [ ] son una lista: cada elemento de la lista es un ítem de n8n.
// Seis elementos = seis ítems = seis tareas.
return [
  // Cada ítem va entre llaves { } y separado del siguiente con una coma.
  {
    // n8n pide que los datos de cada ítem vayan dentro de json.
    json: {
      // Cada línea es clave: valor. La clave es el nombre del dato.
      // Los números van sin comillas.
      id: 1,
      // Los textos van entre comillas dobles.
      titulo: "Presentar declaración mensual de Panadería Don Julio",
      responsable: "Tomás",
      // Valores posibles: pendiente, en_proceso, completada.
      estado: "pendiente",
      // Valores posibles: alta, media, baja.
      prioridad: "alta",
      // Fecha como texto, en formato año-mes-día.
      // Después del último campo no va coma.
      fecha_vencimiento: "2026-11-16"
    }
  },
  {
    json: {
      id: 2,
      titulo: "Liquidar sueldos de noviembre de Ferretería Norte",
      responsable: "Tomás",
      estado: "en_proceso",
      prioridad: "alta",
      fecha_vencimiento: "2026-11-30"
    }
  },
  {
    json: {
      id: 3,
      titulo: "Confirmar reunión de diagnóstico con Café Molino",
      responsable: "Valeria",
      estado: "pendiente",
      prioridad: "media",
      fecha_vencimiento: "2026-11-12"
    }
  },
  {
    json: {
      id: 4,
      titulo: "Archivar comprobantes de octubre",
      responsable: "Tomás",
      estado: "completada",
      prioridad: "baja",
      fecha_vencimiento: "2026-11-10"
    }
  },
  // La tarea 5 está incompleta a propósito: no tiene título.
  // En la Clase 2 el workflow tiene que descartarla.
  {
    json: {
      id: 5,
      titulo: "",
      responsable: "Carolina",
      estado: "pendiente",
      prioridad: "baja",
      fecha_vencimiento: "2026-11-20"
    }
  },
  // Después de la última tarea no va coma.
  {
    json: {
      id: 6,
      titulo: "Preparar propuesta para Taller Mecánico Ruta 3",
      responsable: "Valeria",
      estado: "en_proceso",
      prioridad: "media",
      fecha_vencimiento: "2026-11-18"
    }
  }
];

// Revisa cada tarea y le agrega dos datos: es_valida (true o false) y errores (la lista de lo que falta).
// Este nodo no descarta nada: solo marca. El que descarta es el Filter siguiente.
//
// items es la lista de ítems que llega del nodo anterior (las seis tareas).
// .map recorre la lista y devuelve una lista nueva, del mismo largo, con cada ítem modificado.
return items.map(item => {
  // tarea es un nombre corto para los datos del ítem (lo que está dentro de json).
  const tarea = item.json;
  // Lista vacía: acá se anota cada dato que falta.
  const errores = [];

  // ! significa "no hay". trim() quita los espacios: un título de solo espacios cuenta como vacío.
  // || significa "o": alcanza con que se cumpla una de las dos condiciones.
  if (!tarea.titulo || tarea.titulo.trim() === "") {
    // push agrega un texto al final de la lista de errores.
    errores.push("Falta el título");
  }
  if (!tarea.responsable || tarea.responsable.trim() === "") {
    errores.push("Falta el responsable");
  }
  if (!tarea.estado || tarea.estado.trim() === "") {
    errores.push("Falta el estado");
  }

  // Si la lista de errores quedó vacía (largo 0), la tarea es válida.
  tarea.es_valida = errores.length === 0;
  tarea.errores = errores;
  // Devuelve el mismo ítem, ahora con los dos datos nuevos.
  return item;
});

// Junta las tareas que llegan (las que requieren atención) en UN solo ítem: el resumen de la mañana.
//
// Saca los datos de cada ítem y arma una lista simple de tareas.
const tareas = items.map(item => item.json);

const resumen = {
  // La fecha y hora de ahora, en formato estándar (año-mes-díaThora). Va en hora UTC.
  fecha_generacion: new Date().toISOString(),
  // .length es la cantidad de elementos de la lista.
  cantidad_tareas_atencion: tareas.length,
  // Para cada tarea se copian solo los seis campos de la consigna: es_valida y errores quedan afuera.
  // Los paréntesis alrededor de las llaves ({ ... }) indican que se devuelve un objeto.
  tareas: tareas.map(tarea => ({
    id: tarea.id,
    titulo: tarea.titulo,
    responsable: tarea.responsable,
    estado: tarea.estado,
    prioridad: tarea.prioridad,
    fecha_vencimiento: tarea.fecha_vencimiento
  }))
};

// Un solo ítem: una lista con un elemento, con los datos dentro de json.
return [{ json: resumen }];
